import{_ as e,o as n,c as a,a6 as r}from"./chunks/framework.BrkgobfX.js";const m=JSON.parse('{"title":"扩展是什么","description":"Chrome 插件开发指南 · Chrome 扩展与网页、PWA、用户脚本的区别，以及 MV3 下的运行上下文","frontmatter":{"title":"扩展是什么","description":"Chrome 插件开发指南 · Chrome 扩展与网页、PWA、用户脚本的区别，以及 MV3 下的运行上下文","source":"https://daiw.org/manual/chrome-extension/what-is-extension"},"headers":[],"relativePath":"manual/computer-programming/chrome-extension/what-is-extension.md","filePath":"manual/computer-programming/chrome-extension/what-is-extension.md"}'),o={name:"manual/computer-programming/chrome-extension/what-is-extension.md"};function s(d,t,i,l,c,p){return n(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="扩展是什么" tabindex="-1">扩展是什么 <a class="header-anchor" href="#扩展是什么" aria-label="Permalink to &quot;扩展是什么&quot;">​</a></h1><p>Chrome 插件开发指南 · Chrome 扩展与网页、PWA、用户脚本的区别，以及 MV3 下的运行上下文</p><p>扩展不是「在 Chrome 里打开的一个网站」，而是<strong>安装在浏览器配置文件里、跨标签页存活</strong>的程序包。理解它和网页、PWA、油猴脚本的区别，能避免把插件写成「带 <code>manifest.json</code> 的网页」。</p><h2 id="直觉-四个角色" tabindex="-1">直觉：四个角色 <a class="header-anchor" href="#直觉-四个角色" aria-label="Permalink to &quot;直觉：四个角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>谁运行它</th><th>典型能力</th><th>例子</th></tr></thead><tbody><tr><td>普通网页</td><td>单个标签页</td><td>只能访问自己源、用户打开才存在</td><td><code>https://example.com</code></td></tr><tr><td>PWA</td><td>标签页 + 可安装</td><td>离线缓存、推送（受平台限制）</td><td>记事本 PWA（见 <a href="/Front2Full/manual/computer-programming/chrome-extension/appendix-pwa">附录：PWA 开发指南</a>）</td></tr><tr><td><strong>Chrome 扩展</strong></td><td>浏览器进程 + 可选注入页面</td><td>读改任意允许站点 DOM、拦网络、改工具栏</td><td>广告拦截、翻译、密码管理</td></tr><tr><td>用户脚本（Tampermonkey）</td><td>注入脚本</td><td>改 DOM，能力取决于管理器</td><td>站点美化脚本（见 <a href="/Front2Full/manual/computer-programming/chrome-extension/appendix-userscript">附录：油猴脚本开发指南</a>）</td></tr></tbody></table><p>扩展的核心是 <strong>manifest 声明能力 + 多种 JS 运行上下文</strong>（Service Worker、Content Script、Popup 等），由 Chrome 按权限调度。</p><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p><strong>Chrome 扩展（Extension）</strong> 是一个包含 <code>manifest.json</code> 的目录（或 zip 包），声明：</p><ul><li><strong>元数据</strong>：名称、版本、图标、描述</li><li><strong>入口</strong>：<code>background</code> Service Worker、<code>action</code> 弹出页、<code>content_scripts</code> 注入规则等</li><li><strong>权限</strong>：<code>permissions</code>、<code>host_permissions</code>、可选的 <code>optional_permissions</code></li></ul><p>用户从 <code>chrome://extensions</code> 加载未打包目录，或从 Chrome Web Store 安装后，扩展在<strong>浏览器会话间持久存在</strong>（直到禁用/卸载）。</p><h2 id="mv3-下的三种常见上下文" tabindex="-1">MV3 下的三种常见上下文 <a class="header-anchor" href="#mv3-下的三种常见上下文" aria-label="Permalink to &quot;MV3 下的三种常见上下文&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Chrome 浏览器                                   │</span></span>
<span class="line"><span>│  ┌──────────────┐  ┌─────────────────────────┐ │</span></span>
<span class="line"><span>│  │ Service      │  │ 普通网页（隔离）          │ │</span></span>
<span class="line"><span>│  │ Worker       │◄─┤ Content Script（隔离世界）│ │</span></span>
<span class="line"><span>│  │（扩展后台）   │  │ 注入到 tab 的 DOM        │ │</span></span>
<span class="line"><span>│  └──────┬───────┘  └─────────────────────────┘ │</span></span>
<span class="line"><span>│         │ chrome.runtime.sendMessage            │</span></span>
<span class="line"><span>│  ┌──────▼───────┐  ┌─────────────────────────┐ │</span></span>
<span class="line"><span>│  │ Popup /      │  │ Side Panel / Options    │ │</span></span>
<span class="line"><span>│  │ Side Panel   │  │（扩展页面，extension://）│ │</span></span>
<span class="line"><span>│  └──────────────┘  └─────────────────────────┘ │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><table tabindex="0"><thead><tr><th>上下文</th><th>能否直接访问网页 DOM</th><th>能否用 <code>chrome.*</code> API</th><th>生命周期</th></tr></thead><tbody><tr><td>Service Worker</td><td>否</td><td>是（按 manifest 权限）</td><td>事件驱动，空闲可被回收</td></tr><tr><td>Content Script</td><td>是（隔离世界）</td><td>部分（如 <code>runtime.sendMessage</code>）</td><td>随匹配页面加载/卸载</td></tr><tr><td>Popup / Options</td><td>否（除非 iframe 嵌页面）</td><td>是</td><td>打开时存在，关闭即销毁</td></tr></tbody></table><p><strong>隔离世界（Isolated World）</strong>：Content Script 与页面自己的 JS 共享 DOM，但<strong>不共享</strong> <code>window</code> 上的变量；两边要靠 <code>postMessage</code> 或注入 <code>&lt;script&gt;</code> 桥接（见后文 <a href="/Front2Full/manual/computer-programming/chrome-extension/messaging">消息传递</a>）。</p><h2 id="例子-1-翻译插件在做什么" tabindex="-1">例子 1：翻译插件在做什么 <a class="header-anchor" href="#例子-1-翻译插件在做什么" aria-label="Permalink to &quot;例子 1：翻译插件在做什么&quot;">​</a></h2><ol><li><code>content_scripts</code> 在 <code>*://*/*</code> 匹配页注入 <code>translate.js</code>，监听用户选中文本。</li><li>用户点击扩展图标，<strong>Popup</strong> 显示设置。</li><li><strong>Service Worker</strong> 收到消息，带 <code>host_permissions</code> 请求翻译 API，把结果 <code>sendMessage</code> 回 Content Script 显示浮层。</li></ol><p>没有扩展权限，纯网页无法在读 <code>bank.com</code> 的同时读 <code>news.com</code> 的 DOM。</p><h2 id="例子-2-与-mv2-的关键差异-只需记住三条" tabindex="-1">例子 2：与 MV2 的关键差异（只需记住三条） <a class="header-anchor" href="#例子-2-与-mv2-的关键差异-只需记住三条" aria-label="Permalink to &quot;例子 2：与 MV2 的关键差异（只需记住三条）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>点</th><th>MV2（旧）</th><th>MV3（本专栏）</th></tr></thead><tbody><tr><td>后台</td><td>持久 <code>background.page</code></td><td><strong>事件型 Service Worker</strong></td></tr><tr><td>拦截网络</td><td><code>webRequest</code> 阻塞</td><td><strong>declarativeNetRequest</strong> 声明式规则</td></tr><tr><td>远程代码</td><td>较松</td><td><strong>禁止远程托管可执行代码</strong>；逻辑须打包进扩展</td></tr></tbody></table><p>新提交 Chrome Web Store <strong>必须 MV3</strong>。</p><h2 id="量化-规模直觉" tabindex="-1">量化：规模直觉 <a class="header-anchor" href="#量化-规模直觉" aria-label="Permalink to &quot;量化：规模直觉&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>典型量级</th></tr></thead><tbody><tr><td>最小扩展文件</td><td><code>manifest.json</code> + 1 个 JS，约 <strong>1 KB</strong></td></tr><tr><td>商店热门扩展包体</td><td><strong>1–5 MB</strong>（含图标、WASM、模型等可达数十 MB）</td></tr><tr><td>Service Worker 单次运行时限</td><td>无固定「5 分钟被杀」计时器，但<strong>空闲会休眠</strong>；长任务需 <code>chrome.alarms</code> 或拆片</td></tr><tr><td><code>chrome.storage.local</code> 配额</td><td>约 <strong>10 MB</strong>（可申请 <code>unlimitedStorage</code>）</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>「扩展 = 内嵌网页」</strong>——Popup 是扩展页，但能力来自 manifest 声明的全局权限，不是 <code>&lt;iframe&gt;</code> 能替代的。</li><li><strong>「Content Script 能读页面 JS 变量」</strong>——默认不能；这是安全设计。</li><li><strong>「Service Worker 一直在后台跑」</strong>——MV3 下会被回收；需要持久状态请用 <a href="/Front2Full/manual/computer-programming/chrome-extension/storage">存储 API</a> 或 <code>chrome.alarms</code>。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Chrome 扩展是<strong>跨标签、带特权 API 的浏览器程序</strong>；MV3 用 Service Worker + 声明式网络规则，Content Script 负责「碰网页」，Popup/Side Panel 负责「碰用户」。下一篇准备开发环境，再动手写 <a href="/Front2Full/manual/computer-programming/chrome-extension/hello-world">Hello World</a>。</p><p>→ 下一篇：<a href="/Front2Full/manual/computer-programming/chrome-extension/environment-setup">开发环境准备</a></p>`,27)])])}const g=e(o,[["render",s]]);export{m as __pageData,g as default};
